            if (engine.getValue(other, "track_loaded")) {
                engine.setValue(group, "CloneFromDeck", deck % 2 === 1 ? deck + 1 : deck - 1);
            } else {
                engine.setValue(group, "LoadSelectedTrack", 1);
            }
